const $=id=>document.getElementById(id),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let seed=42,match=generateMatch(seed),engine=new Engine(),cursor=0,now=0,playing=false,view='live',selected=null,approved=null,latestFeatured=null,toastTimer,visionTimer,serverReady=false,aiReady=false,apiToken='',narrationRequest=0,serverStream=null;
let prefs={mode:'player',club:'all',playerId:'p10',lang:'de',metric:'all'};
try{prefs={...prefs,...JSON.parse(localStorage.getItem('touchline-preferences')||'{}')};}catch{}
for(const key of ['mode','club','lang','metric']){const allowed={mode:['fan','analyst','player'],club:['all','harbour','vale'],lang:['de','en','es'],metric:['all','pressure','passing','chances']};if(!allowed[key].includes(prefs[key]))prefs[key]=key==='mode'?'fan':key==='lang'?'de':'all';}if(!player(prefs.playerId))prefs.playerId='p10';
const typeNames={pass:'Pass',shot:'Abschluss',pressure:'Druck',turnover:'Ballverlust',tackle:'Tackle',throw:'Einwurf'},typeIcons={pass:'↗',shot:'◎',pressure:'≋',turnover:'⇄',tackle:'×',throw:'↪'};
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200);}
function savePrefs(){try{localStorage.setItem('touchline-preferences',JSON.stringify(prefs));}catch{}}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function stopStream(){serverStream?.close();serverStream=null;}
function seek(t){stopStream();now=Math.max(0,Math.min(5400,t));engine=new Engine();cursor=0;while(cursor<match.events.length&&match.events[cursor].match_time_s<=now)engine.ingest(match.events[cursor++]);selected=null;approved=null;render();}
function advance(t){now=Math.min(5400,t);while(cursor<match.events.length&&match.events[cursor].match_time_s<=now)engine.ingest(match.events[cursor++]);if(now===5400)playing=false;render();}
function storyMarkup(i,compact=false){const n=narrate(i,prefs);return`<div class="story-meta"><span class="time">${clock(i.match_time_s)}</span><span>${escape(team(i.team_id).short)} · ${escape(player(i.player_id).name)}</span></div><h3 class="${compact?'':'story-title'}">${escape(n.title)}</h3><p class="story-text">${escape(n.text)}</p><button class="proof-button" data-evidence="${i.id}">◈ ${i.evidence_ids.length} Ereignisbelege ansehen <span>↗</span></button>${!compact?`<p class="interpretation">${i.uncertainty==='pattern-not-causality'?'Mustererkennung · plausible Interpretation, kein Kausalitätsnachweis.':'Beobachtung im synthetischen Datensatz · keine Vorhersage.'}</p>`:''}`;}
function renderPitch(){const e=engine.events.at(-1);let html=`<g fill="none" stroke="#8ab18b" stroke-opacity=".42" stroke-width="1.5"><rect x="1" y="1" width="838" height="542"/><path d="M420 1v542"/><circle cx="420" cy="272" r="73"/><circle cx="420" cy="272" r="2" fill="#a2bd90"/><path d="M1 110h132v324H1 M839 110H707v324h132 M1 199h44v146H1 M839 199h-44v146h44"/><circle cx="89" cy="272" r="2"/><circle cx="751" cy="272" r="2"/></g>`;
 const base=[[7,34],[24,10],[21,26],[21,43],[24,58],[40,34],[51,22],[51,46],[70,9],[75,34],[70,59]];
 const tracks=e?.tracking||PLAYERS.map((p,i)=>({player_id:p.id,x:base[i%11][0],y:base[i%11][1]}));
 const pulse=playerPulse(engine.events,seed,prefs.playerId,now), focused=player(prefs.playerId);
 if(pulse.tracking.length>1)html+=`<polyline points="${pulse.tracking.map(t=>`${(focused.team==='harbour'?t.x:105-t.x)*8},${t.y*8}`).join(' ')}" fill="none" stroke="#e5ffc3" stroke-width="4" opacity=".6"/>`;
 for(const t of tracks){const p=player(t.player_id);let x=(p.team==='harbour'?t.x:105-t.x)*8,y=t.y*8;const focus=p.id===prefs.playerId;if(focus)html+=`<circle cx="${x}" cy="${y}" r="23" fill="none" stroke="#e7fac9" stroke-dasharray="3 4"/>`;html+=`<circle cx="${x}" cy="${y}" r="11" fill="${team(p.team).color}" stroke="#10291b" stroke-width="2"/><text x="${x}" y="${y+3.5}" text-anchor="middle" fill="#22321d" font-size="9" font-family="sans-serif" font-weight="700">${p.number}</text>`;}
 const ft=tracks.find(t=>t.player_id===prefs.playerId);if(ft){const fx=Math.max(4,Math.min(648,(focused.team==='harbour'?ft.x:105-ft.x)*8-90)),fy=Math.max(5,ft.y*8-57);html+=`<g><rect x="${fx}" y="${fy}" width="188" height="27" rx="5" fill="#10241c"/><text x="${fx+9}" y="${fy+18}" fill="#e5ffc3" font-size="13" font-family="sans-serif">${escape(focused.name)} · ${pulse.current.index??'—'}</text></g>`;}
 $('tracking-status').textContent=`${focused.name} im Fokus · Laufweg letzte 60 s · ${e?`Positionsstand ${clock(e.match_time_s)} · ${Math.floor(now-e.match_time_s)} s alt`:'noch keine Positionsdaten'} · synthetisch`;
 if(e){const a=e.team_id==='harbour',x=(a?e.start.x:105-e.start.x)*8,y=e.start.y*8,ex=(a?e.end.x:105-e.end.x)*8,ey=e.end.y*8;html+=`<path d="M${x} ${y} L${ex} ${ey}" stroke="#f6f4b0" stroke-width="2.5" stroke-dasharray="6 5"/><circle cx="${ex}" cy="${ey}" r="6" fill="#f9f9df" stroke="#274225" stroke-width="2"/>`;const m=passMetrics(e);$('event-caption').textContent=`${typeNames[e.type]} · ${player(e.player_id).name}${e.type==='shot'&&e.goal?' · TOR':''}`;$('event-measure').textContent=['pass','throw'].includes(e.type)?`${m.distance_m} m · ${m.speed_kmh} km/h`:`Druck ${Math.round(e.pressure*100)}/100`;}
 else{$('event-caption').textContent='Die Geschichte beginnt gleich.';$('event-measure').textContent='105 × 68 m';}$('pitch').innerHTML=html;
}
function renderMetrics(){const s=engine.state(),a=s.stats.harbour,b=s.stats.vale;const passes=a.passes+b.passes,completed=a.completed+b.completed;const all=engine.events.filter(e=>e.type==='pass');const last=all.at(-1);const m=last?passMetrics(last):null;let cards=[['Passgenauigkeit',passes?`${Math.round(completed/passes*100)}%`:'—',`${completed} / ${passes}`,prefs.mode==='analyst'?'Abgeschlossene / versuchte Pässe':'So oft findet der Pass sein Ziel','↗'],['Abschlüsse',`${a.shots} <small>:</small> ${b.shots}`,'HBR / VAL',`Shot Quality: ${a.quality.toFixed(2)} / ${b.quality.toFixed(2)} · Proxy`,'◎'],['Passschwierigkeit',m?`${m.difficulty}<small>/100</small>`:'—','',m?`Letzter Pass · ${m.distance_m} m · heuristisch`:'Wartet auf ersten Pass','⌁'],['Druckereignisse',`${a.pressure} <small>:</small> ${b.pressure}`,'HBR / VAL','Pressing im synthetischen Ereignisstrom','≋']];
 if(prefs.mode==='player'){const p=engine.playerStats[prefs.playerId];cards=[['Laufdistanz',`${(p.distance_m/1000).toFixed(2)}<small>km</small>`,'','Stichproben der synthetischen Laufwege','↗'],['Spitzengeschwindigkeit',`${p.top_speed_kmh.toFixed(1)}<small>km/h</small>`,'',p.top_speed_kmh>=30?'Sprint-Schwelle 30 km/h erreicht':'Sprint-Schwelle: 30 km/h','⌁'],['Pässe',`${p.completed} <small>/ ${p.passes}</small>`,'','Erfolgreich / versucht','↗'],['Abschlüsse',p.shots,'',`${p.goals} Tore · ${player(prefs.playerId).name}`,'◎']];}
 $('metrics').innerHTML=cards.map(([title,value,sub,foot,icon])=>`<article class="metric"><div class="metric-top"><span>${title}</span><span>${icon}</span></div><div class="metric-value">${value}<small>${sub}</small></div><div class="metric-foot">${escape(foot)}</div></article>`).join('');
 $('home-control').textContent=`${s.control}%`;$('away-control').textContent=`${100-s.control}%`;$('control-bar').style.width=`${s.control}%`;$('rhythm-label').textContent=s.chaos>50?`Viele Wechsel · Chaos ${s.chaos}/100`:s.chaos>25?`Offene Phase · Chaos ${s.chaos}/100`:`Ruhigere Phase · Chaos ${s.chaos}/100`;
 $('rhythm-bars').innerHTML=Array.from({length:23},(_,i)=>`<i style="height:${8+((i*13+s.chaos)%32)}px;opacity:${.4+i/40}"></i>`).join('');
}
function render(){const state=engine.state();$('score').innerHTML=`${state.stats.harbour.goals} <em>:</em> ${state.stats.vale.goals}`;$('broadcast-score').textContent=`${state.stats.harbour.goals} : ${state.stats.vale.goals}`;$('match-clock').textContent=clock(now);$('small-clock').textContent=clock(now);$('timeline').value=now;$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'Wiedergabe pausieren':'Wiedergabe starten');$('play-status').textContent=now>=5400?'FULL TIME':playing?'REPLAY RUNNING':'REPLAY PAUSED';
 const stories=personalize(engine.insights,prefs);latestFeatured=stories[0]||null;$('featured').innerHTML=latestFeatured?storyMarkup(latestFeatured):`<div class="story-meta">BEREIT FÜR DEN NÄCHSTEN MOMENT</div><h3 class="story-title">Jede Geschichte braucht einen Anfang.</h3><p class="story-text">${prefs.mode==='player'?'Für diesen Spieler gibt es im gewählten Zeitraum noch keine passende Story. Seine Kennzahlen findest du unter dem Spielfeld.':'Starte den Replay oder springe zur Demo-Szene in Minute 62. Die Engine erklärt wichtige Momente, sobald sie entstehen.'}</p>`;
 $('narrative-source').textContent='Regelbasierte Erzählung';$('ai-narrate').disabled=!latestFeatured;
 renderPitch();renderMetrics();renderPulsePanel(engine.events,seed,prefs.playerId,now);$('event-count').textContent=`${engine.events.length} Events`;$('event-feed').innerHTML=engine.events.slice(-4).reverse().map(e=>`<div class="event-row"><time>${clock(e.match_time_s)}</time><span class="event-type">${typeIcons[e.type]}</span><strong>${escape(player(e.player_id).name)}</strong><small>${typeNames[e.type]}${e.type==='shot'&&e.goal?' · TOR':''}</small></div>`).join('')||'<p class="empty">Wartet auf den Anpfiff.</p>';
 $('story-grid').innerHTML=stories.slice(0,30).map(i=>`<article class="story-card">${storyMarkup(i,true)}<button class="text-button" style="margin-top:14px" data-broadcast="${i.id}">Für Broadcast auswählen ↗</button></article>`).join('')||'<p class="empty">Noch keine passenden Momente. Replay starten oder Filter ändern.</p>';
 if(!selected||!engine.insights.some(i=>i.id===selected.id))selected=stories[0]||null;
 $('broadcast-list').innerHTML=stories.slice(0,12).map(i=>`<button class="broadcast-item ${selected?.id===i.id?'active':''}" data-select="${i.id}"><small>${clock(i.match_time_s)} · ${team(i.team_id).name} · ${i.evidence_ids.length} Belege</small><strong>${escape(narrate(i,prefs).title)}</strong></button>`).join('')||'<p class="empty" style="padding:20px">Noch keine Story verfügbar.</p>';
 renderBroadcast();$('data-stats').innerHTML=`<div><strong>${match.events.length}</strong>Events / Spiel</div><div><strong>22</strong>fiktive Spieler</div><div><strong>${match.events.filter(e=>e.type==='shot').length}</strong>Abschlüsse</div>`;
}
function renderBroadcast(){const delay=Number($('delay').value)||0;const o=selected?overlay(selected,prefs,delay*1000):null;$('overlay-json').textContent=o?JSON.stringify(approved?.insight_id===selected?.id?approved:o,null,2):'Noch keine Story ausgewählt.';const live=approved&&overlayActive(approved,now*1000);
 $('broadcast-overlay').innerHTML=live?`<small>TOUCHLINE · SYNTHETIC INSIGHT</small><h3>${escape(approved.headline)}</h3><p>${escape(approved.body)}</p>`:`<small>${approved?'EINBLENDUNG ABGELAUFEN / NOCH NICHT AKTIV':'REDAKTIONELLE VORSCHAU · NICHT FREIGEGEBEN'}</small><h3>${escape(o?.headline||'Eine Geschichte auswählen.')}</h3><p>${escape(o?.body||'Prüfen, freigeben und passend zur Spieluhr einblenden.')}</p>`;
 $('broadcast-overlay').style.opacity=live?'1':'.55';$('pitch-overlay').hidden=!live;if(live)$('pitch-overlay').innerHTML=`<strong>${escape(approved.headline)}</strong>${escape(approved.body)}`;
 $('approve').disabled=!o;$('overlay-export').disabled=!o;
}
function setView(v){window.scrollTo(0,0);view=v;for(const name of ['live','stories','broadcast','lab','project'])$(name+'-view').hidden=name!==v;document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===v));const names={live:['Match Studio','Mehr als der Spielstand.','Ein Spiel. Viele Perspektiven. Jeder Moment erklärt.'],stories:['Storyboard','Das Spiel erzählt Geschichten.','Die wichtigsten Momente, mit Kontext und Belegen.'],broadcast:['Broadcast','Vom Insight auf den Bildschirm.','Prüfen. Freigeben. Synchronisiert einblenden.'],lab:['Data & Vision Lab','Daten, die du prüfen kannst.','Synthetisch, reproduzierbar und transparent.'],project:['Projekt & Methode','Die Idee hinter Touchline.','Ein überprüfbarer Prototyp für erklärbare Spielintelligenz.']};$('view-label').textContent=names[v][0];$('page-title').textContent=names[v][1];$('page-subtitle').textContent=names[v][2];if(v!=='lab'){clearInterval(visionTimer);visionTimer=null;}$('vision-run').textContent='Frame-Analyse starten ↗';render();}
function evidence(id){const i=engine.insights.find(x=>x.id===id);if(!i)return;const events=i.evidence_ids.map(id=>engine.events.find(e=>e.id===id));$('evidence-body').innerHTML=`<p>${escape(narrate(i,prefs).text)}</p><p><strong>Methode:</strong> ${escape(i.method)} · ${i.uncertainty==='pattern-not-causality'?'Zeitliches Muster, kein bewiesener Ursache-Wirkungs-Zusammenhang.':'Direkt beobachtetes synthetisches Ereignis.'}</p><table class="evidence-table"><thead><tr><th>Zeit</th><th>Ereignis</th><th>Spieler</th><th>Beleg-ID</th></tr></thead><tbody>${events.map(e=>`<tr><td>${clock(e.match_time_s)}</td><td>${typeNames[e.type]}</td><td>${escape(player(e.player_id).name)}</td><td class="evidence-id">${escape(e.id)}</td></tr>`).join('')}</tbody></table><p style="margin-top:20px;color:#849572;font-size:11px">Passschwierigkeit = 50% Distanz + 40% Druck + 10% Querbewegung, begrenzt auf 0–100. Shot Quality = distanz- und druckbasierte Heuristik, nicht anhand echter Spiele kalibriert.</p>`;$('evidence-dialog').showModal();}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.id==='pulse-export'){download('touchline-player-pulse.json',{...playerPulse(engine.events,seed,prefs.playerId,now),player:player(prefs.playerId)});return;}
 if(el.dataset.pulseEvent){const report=playerPulse(engine.events,seed,prefs.playerId,now),c=report.current.contributions.find(c=>c.event_id===el.dataset.pulseEvent),event=engine.events.find(e=>e.id===el.dataset.pulseEvent);if(c&&event){$('evidence-body').innerHTML=`<p><strong>${escape(player(prefs.playerId).name)} · ${clock(c.time_s)} · ${escape(c.label)}</strong></p><p>Aktionsbeitrag vor Begrenzung: ${c.points} Punkte. Sichtbare Indexänderung: ${c.delta>0?'+':''}${c.delta}. Neuer Index: ${c.index}/100. Anzeigeänderungen berücksichtigen Rundung und die Grenzen 0–100.</p><p>Synthetischer Ereignisbeleg: <strong>${escape(c.event_id)}</strong>. Methode: ${report.version}. Die vollständige Formel steht unter dem Spielerprofil.</p><pre>${escape(JSON.stringify(event,null,2))}</pre>`;$('evidence-dialog').showModal();}return;}
 if(el.dataset.view)setView(el.dataset.view);if(el.dataset.evidence)evidence(el.dataset.evidence);if(el.dataset.broadcast){selected=engine.insights.find(i=>i.id===el.dataset.broadcast);approved=null;setView('broadcast');}if(el.dataset.select){selected=engine.insights.find(i=>i.id===el.dataset.select);approved=null;render();}});
for(const [id,key]of [['mode','mode'],['club','club'],['player','playerId'],['language','lang'],['metric-filter','metric']]){$(id).addEventListener('change',()=>{prefs[key]=$(id).value;savePrefs();document.body.classList.toggle('player-mode',prefs.mode==='player');approved=null;$('recap-result').innerHTML='';render();});}
 $('player').innerHTML=PLAYERS.map(p=>`<option value="${p.id}">${p.number} · ${escape(p.name)}</option>`).join('');for(const [id,key]of [['mode','mode'],['club','club'],['player','playerId'],['language','lang'],['metric-filter','metric']])$(id).value=prefs[key];document.body.classList.toggle('player-mode',prefs.mode==='player');
 $('play').onclick=()=>{if(serverStream){stopStream();playing=false;render();return;}if(now>=5400)seek(0);playing=!playing;render();};$('restart').onclick=()=>{playing=false;seek(0);};$('timeline').oninput=()=>{playing=false;seek(Number($('timeline').value));};$('demo').onclick=()=>{playing=false;seek(3750);toast('Demo: sechs belegbare Ereignisse vom Pressing bis zum Tor.');};$('help').onclick=()=>setView('project');$('close-dialog').onclick=()=>$('evidence-dialog').close();
 $('export').onclick=()=>download('touchline-match-report.json',{schema_version:'1.0',synthetic:true,seed,as_of:clock(now),player_pulse:playerPulse(engine.events,seed,prefs.playerId,now),state:engine.state(),preferences:prefs,insights:personalize(engine.insights,prefs),recap:recap(engine,prefs)});
 $('jsonl-export').onclick=()=>download(`touchline-synthetic-${seed}.jsonl`,match.events.map(e=>JSON.stringify(e)).join('\n')+'\n','application/x-ndjson');
 $('regenerate').onclick=()=>{const n=Number($('seed').value);if(!Number.isInteger(n)||n<1||n>999999)return toast('Bitte einen ganzzahligen Seed zwischen 1 und 999999 eingeben.');seed=n;match=generateMatch(seed);$('seed-label').textContent=seed;playing=false;$('recap-result').innerHTML='';seek(0);toast(`Neues synthetisches Spiel mit Seed ${seed} erzeugt.`);};
 $('recap').onclick=()=>{const r=recap(engine,prefs);$('recap-result').innerHTML=`<article class="recap-card"><h3>${escape(r.title)} · ${r.score} · ${clock(now)}</h3>${r.moments.length?r.moments.map(m=>`<div class="recap-moment"><time>${m.time}</time><p><strong>${escape(m.title)}</strong><br>${escape(m.text)}</p></div>`).join(''):'Noch keine passenden Highlights. Spiele zunächst einige Minuten ab.'}<small>Automatisch aus den bis jetzt verarbeiteten Ereignissen. Personalisierte Auswahl · regelbasiert.</small></article>`;};
 $('delay').oninput=()=>{const d=Number($('delay').value);if(!Number.isFinite(d)||d<0||d>120)$('delay').value='0';approved=null;renderBroadcast();};
 $('approve').onclick=()=>{if(!selected)return;approved={...overlay(selected,prefs,(Number($('delay').value)||0)*1000),requires_editor_approval:false,approved:true};const keep=selected;seek(approved.start_ms/1000);selected=keep;approved={...overlay(selected,prefs,(Number($('delay').value)||0)*1000),requires_editor_approval:false,approved:true};playing=true;$('overlay-status').textContent='Lokal freigegeben. Vorschau startet am Einblendzeitpunkt; Ablauf nach 12 Spielsekunden. Für eine ruhige Vorschau 1× wählen.';$('speed').value='1';render();};
 $('overlay-export').onclick=()=>{if(selected)download('touchline-overlay.json',approved||overlay(selected,prefs,(Number($('delay').value)||0)*1000));};
 $('ai-narrate').onclick=async()=>{if(!latestFeatured)return;playing=false;render();if(!serverReady||!aiReady){toast('Azure-KI ist noch nicht verbunden. Die Demo verwendet nachvollziehbare Regeln. Einrichtung siehe Projektpaket.');return;}
  if(!apiToken){apiToken=window.prompt('API-Zugriffstoken des eigenen Touchline-Servers (wird nur im Arbeitsspeicher gehalten):')||'';if(!apiToken)return;}
  const id=++narrationRequest,insight=latestFeatured,prefSnapshot=JSON.stringify(prefs);$('ai-narrate').disabled=true;$('narrative-source').textContent='Azure-KI formuliert …';
  try{const res=await fetch('/api/narrate',{method:'POST',headers:{'content-type':'application/json','authorization':`Bearer ${apiToken}`},body:JSON.stringify({seed,as_of:now,insight_id:insight.id,preferences:prefs}),signal:AbortSignal.timeout(14000)});if(!res.ok)throw Error(res.status===401?'Zugriffstoken nicht gültig.':'Azure-Anfrage nicht verfügbar.');const n=await res.json();if(id!==narrationRequest||latestFeatured?.id!==insight.id||JSON.stringify(prefs)!==prefSnapshot)return;const p=$('featured').querySelector('.story-text');p.textContent=n.text;$('narrative-source').textContent=n.source==='azure-openai'?'Azure OpenAI · redaktioneller Entwurf':'Regelbasiert · KI-Fallback';if(n.warning)toast(n.warning);}catch(e){toast(e.message);$('narrative-source').textContent='Regelbasiert · KI nicht erreichbar';}finally{$('ai-narrate').disabled=false;}
 };
 $('vision-run').onclick=()=>{if(visionTimer){clearInterval(visionTimer);visionTimer=null;$('vision-run').textContent='Frame-Analyse starten ↗';return;}const tracker=new PixelTracker(),ctx=$('vision-canvas').getContext('2d',{willReadFrequently:true});let frame=0;$('vision-run').textContent='Analyse stoppen';visionTimer=setInterval(()=>{const t=frame++/20;if(t>=11.5){clearInterval(visionTimer);visionTimer=null;$('vision-run').textContent='Erneut analysieren ↗';return;}const img=renderSyntheticFrame(ctx,t),out=tracker.infer(img.data,img.width,img.height,t);$('vision-info').textContent=`Frame ${frame} · ${Object.keys(out.detections).length} Objekte · Ball ${out.ball_speed_kmh??'—'} km/h · ${out.passes} Übergaben erkannt${out.newPass?` · ${out.newPass.from} → ${out.newPass.to}: ${out.newPass.distance_m} m`:''}`;},50);};
 const streamButton=document.createElement('button');streamButton.className='button secondary';streamButton.textContent='Server-Livestream starten';$('jsonl-export').after(streamButton);streamButton.onclick=()=>{if(!serverReady)return toast('Server-Livestream ist in der lokalen oder Azure-Installation verfügbar. Diese statische Vorschau nutzt den Browser-Replay.');playing=false;seek(0);setView('live');serverStream=new EventSource(`/api/stream?seed=${seed}&speed=${$('speed').value}`);serverStream.onmessage=event=>{try{const data=JSON.parse(event.data);engine.ingest(data);cursor=data.sequence;now=data.match_time_s;render();$('play-status').textContent='SERVER STREAM';$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','Server-Stream stoppen');}catch{stopStream();toast('Ungültiges Stream-Ereignis abgelehnt.');}};serverStream.addEventListener('complete',()=>{stopStream();now=5400;render();});serverStream.onerror=()=>{toast('Stream unterbrochen. Automatische Wiederverbindung mit letzter Ereignis-ID.');};};
renderSyntheticFrame($('vision-canvas').getContext('2d'),0);seek(3745);
 let last=performance.now();setInterval(()=>{const t=performance.now(),delta=Math.min(1,(t-last)/1000);last=t;if(playing)advance(now+delta*Number($('speed').value));},250);
